#include <iostream>
using namespace std;
int main() {
  int N, H, X, P[111];
  cin >> N >> H >> X;
  for (int n = 1; n <= N; n++) cin >> P[n];
  for (int n = 1; n <= N; n++) {
    if (H + P[n] >= X) {
      cout << n << endl;
      break;
    }
  }
}

N, H, X = map(int, input().split())
P = [*map(int, input().split())]
for n in range(N):
    if H+P[n] >= X:
        print(n+1)
        exit(0)
